Q: Securely rendering hyperlinks in untrusted text A: <p>XSS safe solution to write untrusted input to div with auto creating links.<br />
Can anyone hack this?</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function makeLinks(inputString, el) {
    el.innerHTML = '';
    const findUrlRegex = /(?:(?:https?:\/\/)|(?:www\.))[^\s]+/g;
    const cleanUrlRegex = /^(.+?)([.,?!'"]*)$/;
    let indexOfStartOfString = 0;
    let match;
    do {
        match = findUrlRegex.exec(inputString);
        if (match) {
            const text = inputString.substr(indexOfStartOfString, match.index - indexOfStartOfString);
            el.appendChild(document.createTextNode(text));
            const dirtyUrl = match[0];
            const urlDirtyMatch = cleanUrlRegex.exec(dirtyUrl);
            const a = document.createElement('a');
            a.href = urlDirtyMatch[1];
            a.innerText = urlDirtyMatch[1];
            a.target = '_blank';
            el.appendChild(a);
            indexOfStartOfString = match.index + dirtyUrl.length;
        }
    } while (match);
    const remainingText = inputString.substr(indexOfStartOfString, inputString.length - indexOfStartOfString);
    el.appendChild(document.createTextNode(remainingText));
}

const inputString = document.querySelector('.message__textarea');
const el_message__text = document.querySelector('.message__text');
makeLinks(inputString.value, el_message__text);
document.querySelector('.message_send').addEventListener('click', () =&gt; {
    makeLinks(inputString.value, el_message__text);
});</code></pre>
